    "component_01": _dependency_solver("maximum", "ascending", True),
    "component_02": _dependency_solver("minimum", "ascending", True),
    "component_03": _dependency_solver("maximum", "descending", False),
    "component_04": _dependency_solver("minimum", "descending", False),
    "component_05": _dependency_solver("maximum", "ascending", False),
    "component_06": _ledger,
    "component_07": _quota_intervals,
    "component_08": _routes,
}

